WITH norms(meas0, per, cut, pr) AS (VALUES ('ORF WC','Fall',0,1),('ORF WC','Fall',11,2),('ORF WC','Fall',17,3),('ORF WC','Fall',22,4),('ORF WC','Fall',28,5),('ORF WC','Fall',33,6),('ORF WC','Fall',37,7),('ORF WC','Fall',41,8),('ORF WC','Fall',45,9),('ORF WC','Fall',48,10),('ORF WC','Fall',51,11),('ORF WC','Fall',54,12),('ORF WC','Fall',56,13),('ORF WC','Fall',58,14),('ORF WC','Fall',60,15),('ORF WC','Fall',62,16),('ORF WC','Fall',63,17),('ORF WC','Fall',65,18),('ORF WC','Fall',66,19),('ORF WC','Fall',68,20),('ORF WC','Fall',69,21),('ORF WC','Fall',70,22),('ORF WC','Fall',72,23),('ORF WC','Fall',73,24),('ORF WC','Fall',75,25),('ORF WC','Fall',76,26),('ORF WC','Fall',77,27),('ORF WC','Fall',79,28),('ORF WC','Fall',80,29),('ORF WC','Fall',81,30),('ORF WC','Fall',83,31),('ORF WC','Fall',84,32),('ORF WC','Fall',86,33),('ORF WC','Fall',87,34),('ORF WC','Fall',88,35),('ORF WC','Fall',89,36),('ORF WC','Fall',91,37),('ORF WC','Fall',92,38),('ORF WC','Fall',93,39),('ORF WC','Fall',94,40),('ORF WC','Fall',95,41),('ORF WC','Fall',96,42),('ORF WC','Fall',97,44),('ORF WC','Fall',98,45),('ORF WC','Fall',99,46),('ORF WC','Fall',100,47),('ORF WC','Fall',101,48),('ORF WC','Fall',102,49),('ORF WC','Fall',103,50),('ORF WC','Fall',104,51),('ORF WC','Fall',106,52),('ORF WC','Fall',107,54),('ORF WC','Fall',109,55),('ORF WC','Fall',110,56),('ORF WC','Fall',111,57),('ORF WC','Fall',112,58),('ORF WC','Fall',114,59),('ORF WC','Fall',115,60),('ORF WC','Fall',116,61),('ORF WC','Fall',117,63),('ORF WC','Fall',118,64),('ORF WC','Fall',119,65),('ORF WC','Fall',120,66),('ORF WC','Fall',121,67),('ORF WC','Fall',122,68),('ORF WC','Fall',124,69),('ORF WC','Fall',125,70),('ORF WC','Fall',127,71),('ORF WC','Fall',128,72),('ORF WC','Fall',129,73),('ORF WC','Fall',130,74),('ORF WC','Fall',131,75),('ORF WC','Fall',132,76),('ORF WC','Fall',133,77),('ORF WC','Fall',134,78),('ORF WC','Fall',135,79),('ORF WC','Fall',137,80),('ORF WC','Fall',139,81),('ORF WC','Fall',140,82),('ORF WC','Fall',141,83),('ORF WC','Fall',142,84),('ORF WC','Fall',143,85),('ORF WC','Fall',145,86),('ORF WC','Fall',147,87),('ORF WC','Fall',148,88),('ORF WC','Fall',150,89),('ORF WC','Fall',152,90),('ORF WC','Fall',153,91),('ORF WC','Fall',155,92),('ORF WC','Fall',157,93),('ORF WC','Fall',161,94),('ORF WC','Fall',164,95),('ORF WC','Fall',167,96),('ORF WC','Fall',171,97),('ORF WC','Fall',178,98),('ORF WC','Fall',187,99),('ORF WC','Spring',0,1),('ORF WC','Spring',26,2),('ORF WC','Spring',42,3),('ORF WC','Spring',57,4),('ORF WC','Spring',65,5),('ORF WC','Spring',72,6),('ORF WC','Spring',78,7),('ORF WC','Spring',82,8),('ORF WC','Spring',85,9),('ORF WC','Spring',88,10),('ORF WC','Spring',91,11),('ORF WC','Spring',93,12),('ORF WC','Spring',95,13),('ORF WC','Spring',97,14),('ORF WC','Spring',99,15),('ORF WC','Spring',100,16),('ORF WC','Spring',101,17),('ORF WC','Spring',102,18),('ORF WC','Spring',104,19),('ORF WC','Spring',106,20),('ORF WC','Spring',108,21),('ORF WC','Spring',109,22),('ORF WC','Spring',111,23),('ORF WC','Spring',113,24),('ORF WC','Spring',115,25),('ORF WC','Spring',116,26),('ORF WC','Spring',118,27),('ORF WC','Spring',119,29),('ORF WC','Spring',121,30),('ORF WC','Spring',122,31),('ORF WC','Spring',123,32),('ORF WC','Spring',124,33),('ORF WC','Spring',125,35),('ORF WC','Spring',128,36),('ORF WC','Spring',129,37),('ORF WC','Spring',130,38),('ORF WC','Spring',131,39),('ORF WC','Spring',132,40),('ORF WC','Spring',133,41),('ORF WC','Spring',135,42),('ORF WC','Spring',136,43),('ORF WC','Spring',137,44),('ORF WC','Spring',138,45),('ORF WC','Spring',140,46),('ORF WC','Spring',141,48),('ORF WC','Spring',142,50),('ORF WC','Spring',143,51),('ORF WC','Spring',145,52),('ORF WC','Spring',146,54),('ORF WC','Spring',148,55),('ORF WC','Spring',150,56),('ORF WC','Spring',151,57),('ORF WC','Spring',152,58),('ORF WC','Spring',153,59),('ORF WC','Spring',154,60),('ORF WC','Spring',155,61),('ORF WC','Spring',157,62),('ORF WC','Spring',158,63),('ORF WC','Spring',159,64),('ORF WC','Spring',160,65),('ORF WC','Spring',161,66),('ORF WC','Spring',162,67),('ORF WC','Spring',164,68),('ORF WC','Spring',166,69),('ORF WC','Spring',167,70),('ORF WC','Spring',169,71),('ORF WC','Spring',170,72),('ORF WC','Spring',172,73),('ORF WC','Spring',173,75),('ORF WC','Spring',174,76),('ORF WC','Spring',176,77),('ORF WC','Spring',177,78),('ORF WC','Spring',179,79),('ORF WC','Spring',180,81),('ORF WC','Spring',181,82),('ORF WC','Spring',183,83),('ORF WC','Spring',184,84),('ORF WC','Spring',185,85),('ORF WC','Spring',186,86),('ORF WC','Spring',187,87),('ORF WC','Spring',188,88),('ORF WC','Spring',190,89),('ORF WC','Spring',192,90),('ORF WC','Spring',194,91),('ORF WC','Spring',197,92),('ORF WC','Spring',198,93),('ORF WC','Spring',200,94),('ORF WC','Spring',201,95),('ORF WC','Spring',204,96),('ORF WC','Spring',209,97),('ORF WC','Spring',215,98),('ORF WC','Spring',224,99)),
dst AS (SELECT d.assessment_group AS meas, mp.b0, d.studentid, d."window", AVG(d.score) AS s
  FROM dibels_scores d
  JOIN (VALUES ('ORF WC','Fall')) mp(m0, b0) ON mp.m0 = d.assessment_group
  WHERE d.yearid=35 AND d.grade_level=5 AND d."window" IN (mp.b0, 'Spring')
  GROUP BY 1,2,3,4),
dm AS (SELECT f.meas, f.studentid, f.s AS b, pb.pr AS bs, pe.pr AS es
  FROM dst f
  JOIN dst sp ON sp.studentid=f.studentid AND sp.meas=f.meas AND sp."window"='Spring'
  LEFT JOIN LATERAL (SELECT n.pr FROM norms n WHERE n.meas0=f.meas AND n.per=f.b0 AND n.cut <= f.s ORDER BY n.cut DESC LIMIT 1) pb ON true
  LEFT JOIN LATERAL (SELECT n.pr FROM norms n WHERE n.meas0=sp.meas AND n.per='Spring' AND n.cut <= sp.s ORDER BY n.cut DESC LIMIT 1) pe ON true
  WHERE f."window" = f.b0),
ist AS (SELECT 'iReady Reading' AS meas, studentid, "window", AVG(percentile) AS s
  FROM iready_reading_diagnostics WHERE yearid=35 AND grade_level=5 AND "window" IN ('Fall','Spring') GROUP BY 1,2,3
  UNION ALL
SELECT 'iReady Math' AS meas, studentid, "window", AVG(percentile) AS s
  FROM iready_math_diagnostics WHERE yearid=35 AND grade_level=5 AND "window" IN ('Fall','Spring') GROUP BY 1,2,3),
im AS (SELECT f.meas, f.studentid, f.s AS b, f.s AS bs, sp.s AS es
  FROM ist f JOIN ist sp ON sp.studentid=f.studentid AND sp.meas=f.meas AND sp."window"='Spring'
  WHERE f."window" <> 'Spring'),
m AS (SELECT * FROM dm UNION ALL SELECT * FROM im),
sch AS (SELECT DISTINCT studentid FROM school_year_enrollments WHERE yearid=35 AND schoolid=3055 AND grade_level=5),
mm AS (SELECT m.*, (sch.studentid IS NOT NULL) AS in_sch
       FROM m LEFT JOIN sch ON sch.studentid=m.studentid),
q AS (SELECT mm.*,
        NTILE(4) OVER (PARTITION BY meas, in_sch ORDER BY b, studentid) AS q_sch,
        NTILE(4) OVER (PARTITION BY meas ORDER BY b, studentid) AS q_dist
      FROM mm),
schq AS (SELECT meas, COALESCE(q_sch::text,'All') AS qt,
           ROUND(AVG(bs),0) AS s_start, ROUND(AVG(es),0) AS s_end, COUNT(*) AS n_sch
         FROM q WHERE in_sch GROUP BY GROUPING SETS ((meas, q_sch),(meas))),
distq AS (SELECT meas, COALESCE(q_dist::text,'All') AS qt,
           ROUND(AVG(bs),0) AS d_start, ROUND(AVG(es),0) AS d_end, COUNT(*) AS n_dist
          FROM q GROUP BY GROUPING SETS ((meas, q_dist),(meas)))
SELECT meas, qt, s_start, s_end, n_sch, d_start, d_end, n_dist
FROM distq LEFT JOIN schq USING (meas, qt)
ORDER BY meas, qt